//! `systemd --user` units for `cg daemon`, with no hidden state.
//!
//! Two files are generated from one [`ServiceSpec`]:
//!
//! * `<name>.service` — one cycle (`daemon --once`) or a long-running daemon;
//! * `<name>.timer` — timer mode only, fires the oneshot service.
//!
//! Rules:
//!
//! * a unit not marked as generated by cg is never overwritten or removed;
//! * every `systemctl` call goes through one seam, so tests patch one place;
//! * writes are atomic, so `Ctrl+C` never leaves half a unit behind.

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::error::{Error, Result};
use crate::note::atomic_write;

/// First line of every generated unit; also the ownership marker.
pub const MARKER: &str = "# Generated by cg services";
const DEFAULT_NAME: &str = "cg";
const DEFAULT_EVERY: &str = "1h";

/// How the daemon should be scheduled.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Oneshot service fired by a timer.
    Timer,
    /// Long-running process with `Restart=on-failure`.
    Daemon,
}

impl Mode {
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value {
            "timer" => Some(Self::Timer),
            "daemon" => Some(Self::Daemon),
            _ => None,
        }
    }

    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Timer => "timer",
            Self::Daemon => "daemon",
        }
    }
}

/// Everything needed to render and install a unit pair.
#[derive(Debug, Clone)]
pub struct ServiceSpec {
    pub name: String,
    pub mode: Mode,
    pub apply: bool,
    /// Timer interval (`30m`, `2h`, `1d`, or bare seconds).
    pub every: String,
    pub wait_min: Option<u64>,
    pub wait_max: Option<u64>,
    pub unit_dir: PathBuf,
    /// Command that starts cg (normally the absolute path of `cg`).
    pub cg_argv: Vec<String>,
}

impl ServiceSpec {
    /// Validate user input before touching the filesystem.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        name: &str,
        mode: Mode,
        every: &str,
        wait_min: Option<u64>,
        wait_max: Option<u64>,
        apply: bool,
        unit_dir: Option<&Path>,
        cg_bin: Option<&Path>,
    ) -> Result<Self> {
        let name = if name.is_empty() { DEFAULT_NAME } else { name };
        if !valid_unit_name(name) {
            return Err(Error::usage(format!(
                "nome inválido: {name:?} (use letras, números, _ . @ -)"
            )));
        }
        let every = if every.is_empty() {
            DEFAULT_EVERY
        } else {
            every
        };
        parse_duration(every)?;
        if wait_min.zip(wait_max).is_some_and(|(min, max)| max < min) {
            return Err(Error::usage("--wait-max precisa ser >= --wait-min"));
        }
        let cg_argv = detect_cg_argv(cg_bin)?;
        Ok(Self {
            name: name.to_owned(),
            mode,
            apply,
            every: every.to_owned(),
            wait_min,
            wait_max,
            unit_dir: resolve_unit_dir(unit_dir),
            cg_argv,
        })
    }

    #[must_use]
    pub fn service_path(&self) -> PathBuf {
        self.unit_dir.join(format!("{}.service", self.name))
    }

    #[must_use]
    pub fn timer_path(&self) -> PathBuf {
        self.unit_dir.join(format!("{}.timer", self.name))
    }

    #[must_use]
    pub fn service_unit(&self) -> String {
        format!("{}.service", self.name)
    }

    #[must_use]
    pub fn timer_unit(&self) -> String {
        format!("{}.timer", self.name)
    }

    #[must_use]
    pub fn uses_timer(&self) -> bool {
        self.mode == Mode::Timer
    }

    /// The command systemd will run.
    #[must_use]
    pub fn exec_argv(&self) -> Vec<String> {
        let mut argv = self.cg_argv.clone();
        argv.push("daemon".to_owned());
        if self.uses_timer() {
            argv.push("--once".to_owned());
        }
        if self.apply {
            argv.push("--yes".to_owned());
        }
        if !self.uses_timer() {
            if let Some(min) = self.wait_min {
                argv.extend(["--min-sleep".to_owned(), min.to_string()]);
            }
            if let Some(max) = self.wait_max {
                argv.extend(["--max-sleep".to_owned(), max.to_string()]);
            }
        }
        argv
    }
}

/// Unit directory: flag, then `CG_UNIT_DIR`, then XDG config.
#[must_use]
pub fn resolve_unit_dir(explicit: Option<&Path>) -> PathBuf {
    if let Some(path) = explicit {
        return path.to_path_buf();
    }
    if let Some(path) = std::env::var_os("CG_UNIT_DIR").map(PathBuf::from) {
        return path;
    }
    let base = std::env::var_os("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .or_else(|| std::env::var_os("HOME").map(|home| PathBuf::from(home).join(".config")))
        .unwrap_or_else(|| PathBuf::from(".config"));
    base.join("systemd").join("user")
}

/// Prefer the installed `cg` in `$PATH`, then this executable.
fn detect_cg_argv(explicit: Option<&Path>) -> Result<Vec<String>> {
    if let Some(path) = explicit {
        return Ok(vec![path.to_string_lossy().into_owned()]);
    }
    if let Some(path) = which("cg") {
        let resolved = std::fs::canonicalize(&path).unwrap_or(path);
        return Ok(vec![resolved.to_string_lossy().into_owned()]);
    }
    let current = std::env::current_exe()
        .map_err(|error| Error::usage(format!("não sei qual binário usar: {error}")))?;
    Ok(vec![current.to_string_lossy().into_owned()])
}

fn which(name: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    std::env::split_paths(&path)
        .map(|dir| dir.join(name))
        .find(|candidate| candidate.is_file())
}

fn valid_unit_name(name: &str) -> bool {
    !name.is_empty()
        && !name.starts_with('.')
        && name != ".."
        && name
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '@' | '-'))
}

/// `30m`, `2h`, `1d` or a bare number of seconds -> seconds.
pub fn parse_duration(text: &str) -> Result<u64> {
    let text = text.trim().to_lowercase();
    let (digits, unit) = match text.chars().last() {
        Some(ch) if ch.is_ascii_alphabetic() => text.split_at(text.len() - 1),
        _ => (text.as_str(), ""),
    };
    let multiplier = match unit {
        "" | "s" => 1,
        "m" => 60,
        "h" => 3_600,
        "d" => 86_400,
        _ => 0,
    };
    if digits.is_empty() || !digits.chars().all(|ch| ch.is_ascii_digit()) || multiplier == 0 {
        return Err(Error::usage(format!(
            "duração inválida: {text:?} (use 30m, 1h, 2d)"
        )));
    }
    let value = digits
        .parse::<u64>()
        .map_err(|_| Error::usage(format!("duração inválida: {text:?} (use 30m, 1h, 2d)")))?;
    let seconds = value
        .checked_mul(multiplier)
        .ok_or_else(|| Error::usage("duração grande demais"))?;
    if seconds == 0 {
        return Err(Error::usage("a duração precisa ser maior que zero"));
    }
    Ok(seconds)
}

#[must_use]
pub fn format_duration(seconds: u64) -> String {
    for (suffix, size) in [("d", 86_400), ("h", 3_600), ("m", 60), ("s", 1)] {
        if seconds.is_multiple_of(size) {
            return format!("{}{suffix}", seconds / size);
        }
    }
    format!("{seconds}s")
}

fn jitter_delay(seconds: u64) -> u64 {
    (seconds / 10).clamp(1, 300)
}

/// Quote one `ExecStart` argument for systemd's own parser.
#[must_use]
pub fn unit_quote(arg: &str) -> String {
    let escaped = arg
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('%', "%%")
        .replace('$', "$$");
    let safe = arg
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || "_./:@+=,-".contains(ch));
    if safe {
        escaped
    } else {
        format!("\"{escaped}\"")
    }
}

#[must_use]
pub fn exec_start(argv: &[String]) -> String {
    argv.iter()
        .map(|arg| unit_quote(arg))
        .collect::<Vec<_>>()
        .join(" ")
}

#[must_use]
pub fn render_service(spec: &ServiceSpec) -> String {
    let mut lines = vec![
        MARKER.to_owned(),
        "[Unit]".to_owned(),
        if spec.uses_timer() {
            "Description=cg daemon (one cycle, systemd timer)".to_owned()
        } else {
            "Description=cg daemon (long-running)".to_owned()
        },
        String::new(),
        "[Service]".to_owned(),
        format!(
            "Type={}",
            if spec.uses_timer() {
                "oneshot"
            } else {
                "simple"
            }
        ),
        format!("ExecStart={}", exec_start(&spec.exec_argv())),
    ];
    if spec.uses_timer() {
        lines.push("TimeoutStartSec=2h".to_owned());
    } else {
        lines.extend(
            [
                "Restart=on-failure",
                "RestartSec=60",
                "SuccessExitStatus=143",
                "KillSignal=SIGTERM",
                "TimeoutStopSec=30",
            ]
            .map(str::to_owned),
        );
    }
    lines.extend(["Nice=10".to_owned(), "IOSchedulingClass=idle".to_owned()]);
    if !spec.uses_timer() {
        lines.extend([
            String::new(),
            "[Install]".to_owned(),
            "WantedBy=default.target".to_owned(),
        ]);
    }
    format!("{}\n", lines.join("\n"))
}

#[must_use]
pub fn render_timer(spec: &ServiceSpec) -> String {
    let seconds = parse_duration(&spec.every).unwrap_or(3_600);
    format!(
        "{}\n",
        [
            MARKER.to_owned(),
            "[Unit]".to_owned(),
            "Description=cg daemon timer".to_owned(),
            String::new(),
            "[Timer]".to_owned(),
            "OnBootSec=2min".to_owned(),
            format!("OnUnitActiveSec={}", format_duration(seconds)),
            format!(
                "RandomizedDelaySec={}",
                format_duration(jitter_delay(seconds))
            ),
            "AccuracySec=1min".to_owned(),
            format!("Unit={}", spec.service_unit()),
            String::new(),
            "[Install]".to_owned(),
            "WantedBy=timers.target".to_owned(),
        ]
        .join("\n")
    )
}

/// True when the file starts with the ownership marker.
#[must_use]
pub fn is_managed(path: &Path) -> bool {
    let Ok(bytes) = std::fs::read(path) else {
        return false;
    };
    bytes.starts_with(MARKER.as_bytes())
}

/// Write atomically; returns true when the file actually changed.
pub fn write_unit(path: &Path, text: &str) -> Result<bool> {
    if std::fs::read_to_string(path).ok().as_deref() == Some(text) {
        return Ok(false);
    }
    atomic_write(path, text.as_bytes())?;
    set_mode(path)?;
    Ok(true)
}

#[cfg(unix)]
fn set_mode(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt as _;
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o644))?;
    Ok(())
}

#[cfg(not(unix))]
fn set_mode(_path: &Path) -> Result<()> {
    Ok(())
}

fn remove_unit(path: &Path) -> Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    std::fs::remove_file(path)?;
    Ok(true)
}

/// Units that cg generated, sorted by name.
#[must_use]
pub fn discover_units(unit_dir: &Path) -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(unit_dir) else {
        return Vec::new();
    };
    let mut units = entries
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| {
            path.is_file()
                && path
                    .extension()
                    .and_then(|ext| ext.to_str())
                    .is_some_and(|ext| ext == "service" || ext == "timer")
                && is_managed(path)
        })
        .collect::<Vec<_>>();
    units.sort();
    units
}

fn refuse_foreign(paths: &[PathBuf], force: bool) -> Result<()> {
    if force {
        return Ok(());
    }
    for path in paths {
        if path.exists() && !is_managed(path) {
            return Err(Error::usage(format!(
                "{} não foi criado pelo cg.\n  Use --force para substituir ou \
                 escolha outro --name.",
                path.display()
            )));
        }
    }
    Ok(())
}

/// Run `systemctl --user ...`; print the command when dry-running.
///
/// Returns the exit status. A missing `systemctl` is 127 and only warns when
/// `quiet` is false.
#[must_use]
pub fn systemctl(args: &[&str], dry_run: bool, quiet: bool) -> i32 {
    if dry_run {
        println!("+ systemctl --user {}", args.join(" "));
        return 0;
    }
    let output = Command::new("systemctl").arg("--user").args(args).output();
    if let Ok(output) = output {
        if !quiet && !output.status.success() {
            eprint!("{}", String::from_utf8_lossy(&output.stderr));
        }
        output.status.code().unwrap_or(1)
    } else {
        if !quiet {
            eprintln!(
                "warning: systemctl não encontrado; unidades gravadas, mas não \
                 ativadas."
            );
        }
        127
    }
}

/// `systemctl --user ...` capturing stdout (for `status`).
///
/// `is-active` and `is-enabled` exit non-zero for inactive/disabled units but
/// still print the useful word, so the exit status is not a filter here.
fn systemctl_capture(args: &[&str]) -> String {
    Command::new("systemctl")
        .arg("--user")
        .args(args)
        .output()
        .ok()
        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_owned())
        .unwrap_or_default()
}

fn rendered(spec: &ServiceSpec) -> Vec<(PathBuf, String)> {
    let mut pairs = vec![(spec.service_path(), render_service(spec))];
    if spec.uses_timer() {
        pairs.push((spec.timer_path(), render_timer(spec)));
    }
    pairs
}

fn print_units(pairs: &[(PathBuf, String)]) {
    for (path, text) in pairs {
        println!("# {}", path.display());
        println!("{}", text.trim_end());
        println!();
    }
}

pub fn show(spec: &ServiceSpec) -> Result<i32> {
    print_units(&rendered(spec));
    Ok(0)
}

/// Report the cg units already installed in the unit directory.
///
/// Read-only: no file is written and no systemd verb is called beyond the
/// query-only `is-active`/`is-enabled`. This is the default `cg services`
/// action, so a user can see what is installed before deciding to register.
pub fn discover(spec: &ServiceSpec) -> Result<i32> {
    let units = discover_existing(&spec.unit_dir, &spec.name);
    if units.is_empty() {
        println!("nenhuma unidade cg em {}", spec.unit_dir.display());
        println!("\nnada foi alterado. Ver o que seria criado: cg services show");
        return Ok(0);
    }

    // systemd only knows the default unit directory; a test/alternate
    // `--unit-dir` cannot be queried through `systemctl --user`.
    let queryable = spec.unit_dir == resolve_unit_dir(None);

    println!("unidades em {}:", spec.unit_dir.display());
    for path in units {
        let unit = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("?");
        let managed = is_managed(&path);
        if !queryable {
            println!(
                "{unit:20} {} (fora do systemd --user)",
                if managed { "gerida" } else { "estranha" }
            );
            continue;
        }
        let active = systemctl_capture(&["is-active", unit]);
        let enabled = systemctl_capture(&["is-enabled", unit]);
        println!(
            "{unit:20} {} ativo={:10} enabled={}",
            if managed { "gerida" } else { "estranha" },
            if active.is_empty() {
                "desconhecido"
            } else {
                &active
            },
            if enabled.is_empty() {
                "desconhecido"
            } else {
                &enabled
            }
        );
    }
    println!("\nnada foi alterado.");
    Ok(0)
}

/// Units for this name or generated by cg, sorted and de-duplicated.
fn discover_existing(unit_dir: &Path, name: &str) -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(unit_dir) else {
        return Vec::new();
    };
    let mut units = entries
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| {
            path.is_file()
                && path
                    .extension()
                    .and_then(|ext| ext.to_str())
                    .is_some_and(|ext| ext == "service" || ext == "timer")
                && (is_managed(path)
                    || path
                        .file_stem()
                        .and_then(|stem| stem.to_str())
                        .is_some_and(|stem| stem == name))
        })
        .collect::<Vec<_>>();
    units.sort();
    units.dedup();
    units
}

/// Write, reload, and (unless `activate` is false) enable the units.
pub fn register(spec: &ServiceSpec, activate: bool, dry_run: bool, force: bool) -> Result<i32> {
    let pairs = rendered(spec);
    let stale_timer = (!spec.uses_timer())
        .then(|| spec.timer_path())
        .filter(|path| path.exists());
    let mut check = pairs
        .iter()
        .map(|(path, _)| path.clone())
        .collect::<Vec<_>>();
    if let Some(timer) = &stale_timer {
        check.push(timer.clone());
    }
    if !force {
        let foreign = check
            .iter()
            .filter(|path| path.exists() && !is_managed(path))
            .collect::<Vec<_>>();
        if !foreign.is_empty() {
            println!("unidades existentes não foram criadas pelo cg:");
            for path in foreign {
                println!("  {}", path.display());
            }
            println!("\nnada foi alterado. Use --force para substituir ou escolha outro --name.");
            return Ok(0);
        }
    }

    let unit = if spec.uses_timer() {
        spec.timer_unit()
    } else {
        spec.service_unit()
    };

    if dry_run {
        print_units(&pairs);
        if let Some(timer) = &stale_timer {
            let _ = systemctl(&["stop", &spec.service_unit()], true, true);
            let _ = systemctl(&["disable", "--now", &spec.timer_unit()], true, true);
            println!("# remover {}", timer.display());
        }
        let _ = systemctl(&["daemon-reload"], true, true);
        if activate {
            let _ = systemctl(&["enable", "--now", &unit], true, true);
        }
        return Ok(0);
    }

    let mut changed = 0_usize;
    for (path, text) in &pairs {
        changed += usize::from(write_unit(path, text)?);
    }
    if let Some(timer) = &stale_timer {
        let _ = systemctl(&["stop", &spec.service_unit()], false, true);
        let _ = systemctl(&["disable", "--now", &spec.timer_unit()], false, true);
        changed += usize::from(remove_unit(timer)?);
    }

    let reload = systemctl(&["daemon-reload"], false, true);
    if reload != 0 {
        eprintln!(
            "warning: systemctl --user falhou; as unidades estão em {} e podem \
             ser ativadas depois.",
            spec.unit_dir.display()
        );
        return Ok(reload);
    }

    let mut code = 0;
    if activate {
        code = systemctl(&["enable", "--now", &unit], false, false);
    }

    println!("nome    : {}", spec.name);
    println!("modo    : {}", spec.mode.as_str());
    println!("serviço : {}", spec.service_path().display());
    if spec.uses_timer() {
        println!("timer   : {}", spec.timer_path().display());
    }
    println!("arquivos: {changed} atualizado(s)");
    if activate && code == 0 {
        println!("estado  : {unit} ativado e iniciado");
    } else if activate {
        eprintln!(
            "estado  : unidade gravada; ative com `systemctl --user enable --now \
             {unit}`"
        );
    } else {
        println!("estado  : unidade gravada, não ativada ({unit})");
    }
    Ok(code)
}

pub fn unregister(spec: &ServiceSpec, dry_run: bool, force: bool) -> Result<i32> {
    let existing = [spec.service_path(), spec.timer_path()]
        .into_iter()
        .filter(|path| path.exists())
        .collect::<Vec<_>>();
    refuse_foreign(&existing, force)?;

    let units = [spec.timer_unit(), spec.service_unit()];
    if dry_run {
        for unit in &units {
            let _ = systemctl(&["disable", "--now", unit], true, true);
        }
        for path in &existing {
            println!("# remover {}", path.display());
        }
        let _ = systemctl(&["daemon-reload"], true, true);
        return Ok(0);
    }

    for unit in &units {
        let _ = systemctl(&["disable", "--now", unit], false, true);
    }
    let mut removed = 0_usize;
    for path in &existing {
        removed += usize::from(remove_unit(path)?);
    }
    let reload = systemctl(&["daemon-reload"], false, true);

    println!("nome    : {}", spec.name);
    println!("removido: {removed} arquivo(s)");
    if reload != 0 && reload != 127 {
        eprintln!(
            "warning: systemctl --user não recarregou; rode `systemctl --user \
             daemon-reload` na mão."
        );
    }
    Ok(0)
}

pub fn status(spec: &ServiceSpec) -> Result<i32> {
    let service_exists = spec.service_path().exists();
    let timer_exists = spec.timer_path().exists();
    println!("nome    : {}", spec.name);
    println!(
        "serviço : {} ({})",
        spec.service_path().display(),
        if service_exists { "ok" } else { "ausente" }
    );
    println!(
        "timer   : {} ({})",
        spec.timer_path().display(),
        if timer_exists { "ok" } else { "ausente" }
    );
    if !service_exists && !timer_exists {
        println!("\nnada registrado — rode `cg services register`.");
        return Ok(1);
    }
    println!(
        "modo    : {}",
        if timer_exists { "timer" } else { "daemon" }
    );

    let mut units = Vec::new();
    if timer_exists {
        units.push(spec.timer_unit());
    }
    if service_exists {
        units.push(spec.service_unit());
    }
    for unit in &units {
        let active = systemctl_capture(&["is-active", unit]);
        let enabled = systemctl_capture(&["is-enabled", unit]);
        println!(
            "{unit:18} ativo={:12} enabled={}",
            if active.is_empty() {
                "desconhecido"
            } else {
                &active
            },
            if enabled.is_empty() {
                "desconhecido"
            } else {
                &enabled
            }
        );
    }

    if timer_exists {
        let next = systemctl_capture(&[
            "show",
            "-p",
            "NextElapseUSecRealtime",
            "--value",
            &spec.timer_unit(),
        ]);
        if !next.is_empty() && next != "n/a" {
            println!("próximo : {next}");
        }
    }
    Ok(0)
}

pub fn action(spec: &ServiceSpec, verb: &str, now: bool, dry_run: bool) -> Result<i32> {
    let service_exists = spec.service_path().exists();
    let timer_exists = spec.timer_path().exists();
    if !service_exists && !timer_exists {
        return Err(Error::usage(format!(
            "{} não está registrado.\n  Rode `cg services register` primeiro.",
            spec.name
        )));
    }
    let target = if timer_exists {
        spec.timer_unit()
    } else {
        spec.service_unit()
    };

    let code = match verb {
        "start" => systemctl(&["start", &target], dry_run, false),
        "stop" => {
            let mut code = 0;
            if timer_exists {
                code |= systemctl(&["stop", &spec.timer_unit()], dry_run, false);
            }
            if service_exists {
                code |= systemctl(&["stop", &spec.service_unit()], dry_run, false);
            }
            code
        }
        "restart" => {
            let stopped = action(spec, "stop", false, dry_run)?;
            if stopped != 0 {
                stopped
            } else {
                action(spec, "start", false, dry_run)?
            }
        }
        "enable" => {
            let mut args = vec!["enable"];
            if now {
                args.push("--now");
            }
            args.push(&target);
            systemctl(&args, dry_run, false)
        }
        "disable" => {
            let mut args = vec!["disable"];
            if now {
                args.push("--now");
            }
            args.push(&target);
            let mut code = systemctl(&args, dry_run, false);
            if timer_exists && (now || !service_exists) {
                code |= systemctl(&["disable", &spec.service_unit()], dry_run, false);
            }
            code
        }
        "run" => {
            if timer_exists {
                systemctl(&["start", &spec.service_unit()], dry_run, false)
            } else {
                systemctl(&["restart", &spec.service_unit()], dry_run, false)
            }
        }
        other => return Err(Error::usage(format!("ação desconhecida: {other}"))),
    };
    Ok(code)
}

pub fn logs(spec: &ServiceSpec, lines: usize, follow: bool, dry_run: bool) -> Result<i32> {
    let mut args = vec![
        "journalctl".to_owned(),
        "--user".to_owned(),
        "-u".to_owned(),
        spec.service_unit(),
        "-n".to_owned(),
        lines.to_string(),
        "--no-pager".to_owned(),
    ];
    if follow {
        args.push("-f".to_owned());
    }
    if dry_run {
        println!("+ {}", args.join(" "));
        return Ok(0);
    }
    let status = Command::new("journalctl")
        .args(&args[1..])
        .status()
        .map_err(|_| Error::usage("warning: journalctl não encontrado."))?;
    Ok(status.code().unwrap_or(1))
}

pub fn list_registered(unit_dir: &Path) -> Result<i32> {
    let units = discover_units(unit_dir);
    if units.is_empty() {
        println!("nenhuma unidade cg em {}", unit_dir.display());
        return Ok(0);
    }
    for unit in units {
        let stem = unit
            .file_stem()
            .and_then(|stem| stem.to_str())
            .unwrap_or("?");
        let kind = unit.extension().and_then(|ext| ext.to_str()).unwrap_or("?");
        println!("{stem:20} {kind:8} {}", unit.display());
    }
    Ok(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn durations_parse_and_format() {
        assert_eq!(parse_duration("30m").expect("30m"), 1_800);
        assert_eq!(parse_duration("2h").expect("2h"), 7_200);
        assert_eq!(parse_duration("1d").expect("1d"), 86_400);
        assert_eq!(parse_duration("90").expect("90"), 90);
        assert!(parse_duration("0m").is_err());
        assert!(parse_duration("10x").is_err());
        assert!(parse_duration("").is_err());
        assert_eq!(format_duration(3_600), "1h");
        assert_eq!(format_duration(90), "90s");
    }

    #[test]
    fn quotes_only_when_needed() {
        assert_eq!(unit_quote("/usr/bin/cg"), "/usr/bin/cg");
        assert_eq!(unit_quote("/tmp/a b"), "\"/tmp/a b\"");
        assert_eq!(unit_quote("/tmp/100%"), "\"/tmp/100%%\"");
        assert_eq!(unit_quote("/tmp/$HOME"), "\"/tmp/$$HOME\"");
    }

    fn spec(mode: Mode) -> ServiceSpec {
        ServiceSpec::new(
            "cg",
            mode,
            "1h",
            None,
            None,
            false,
            Some(Path::new("/tmp/units")),
            Some(Path::new("/usr/bin/cg")),
        )
        .expect("spec")
    }

    #[test]
    fn timer_service_runs_one_cycle() {
        let spec = spec(Mode::Timer);
        let unit = render_service(&spec);
        assert!(unit.starts_with(MARKER));
        assert!(unit.contains("Type=oneshot"));
        assert!(unit.contains("ExecStart=/usr/bin/cg daemon --once"));
        assert!(unit.contains("TimeoutStartSec=2h"));
    }

    #[test]
    fn daemon_service_restarts() {
        let mut spec = spec(Mode::Daemon);
        spec.apply = true;
        spec.wait_min = Some(300);
        let unit = render_service(&spec);
        assert!(unit.contains("Type=simple"));
        assert!(unit.contains("daemon --yes --min-sleep 300"));
        assert!(unit.contains("Restart=on-failure"));
    }

    #[test]
    fn timer_renders_interval_and_jitter() {
        let timer = render_timer(&spec(Mode::Timer));
        assert!(timer.contains("OnUnitActiveSec=1h"));
        assert!(timer.contains("RandomizedDelaySec=5m"));
        assert!(timer.contains("Unit=cg.service"));
    }

    #[test]
    fn discovery_finds_managed_and_matching_units() {
        let dir = tempfile::tempdir().expect("tempdir");
        let foreign = dir.path().join("cg.service");
        std::fs::write(&foreign, "[Unit]\nDescription=mine\n").expect("seed");
        let managed = dir.path().join("cg.timer");
        std::fs::write(&managed, format!("{MARKER}\n[Timer]\n")).expect("seed");
        let unrelated = dir.path().join("other.service");
        std::fs::write(&unrelated, "[Unit]\nDescription=other\n").expect("seed");
        std::fs::write(dir.path().join("notes.txt"), "x").expect("seed");

        assert_eq!(discover_existing(dir.path(), "cg"), vec![foreign, managed]);
    }

    #[test]
    fn invalid_names_are_rejected() {
        assert!(
            ServiceSpec::new("../evil", Mode::Timer, "1h", None, None, false, None, None).is_err()
        );
        assert!(
            ServiceSpec::new(".hidden", Mode::Timer, "1h", None, None, false, None, None).is_err()
        );
    }

    #[test]
    fn foreign_units_are_never_touched() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("cg.service");
        std::fs::write(&path, "[Unit]\nDescription=mine\n").expect("seed");
        assert!(!is_managed(&path));
        assert!(refuse_foreign(&[path], false).is_err());
    }

    #[test]
    fn managed_units_round_trip() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("cg.service");
        let spec = spec(Mode::Timer);
        assert!(write_unit(&path, &render_service(&spec)).expect("write"));
        assert!(is_managed(&path));
        assert_eq!(discover_units(dir.path()), vec![path]);
    }
}
